\label{gk_corollary}
Let $V$ is an irreducible cuspidal representation of $GL_n(\mathcal{K})$, then restrictiom to to representation of $GL_{n-1}(\mathcal{K})$ gives
\begin{equation}
    V|_{GL_{n-1}(\mathcal{K})}= ind_{U_n}^{P_n} \theta = ind_{U_{n-1}}^{P_{n-1}} \theta|_{GL_{n-1}(\mathcal{K})}
\end{equation}
(here and below by $ind$ we mean the functor of induction with compact support). In particular, for $n=2$ we get
\begin{equation}
    V|_{GL_1} \simeq C^\infty(GL_1(\mathcal{K}))
\end{equation}

Let $I^0 \subset I$ be the unipotent radical of the Iwahori subgroup $I \subset PGL(2,\mathcal{K})$, that is the preimage of the unipotent radical of the standard Borel subgroup under the ``evaluation at zero" map $ev_0:G(\mathcal{O}) \to G$. In explicit terms, $I^0$ is given by 
    \begin{equation}
        I^0 = \left\{ \begin{pmatrix}
            1+ta & b \\
            tc  & 1+td
        \end{pmatrix} \text{ with arbitrary } a,b,c,d \in \mathcal{O} \right\}.
    \end{equation}
    We define the group $A= I^0 \rtimes\mathbb{Z}/2\mathbb{Z} \hookrightarrow PGL(2,\mathcal{K})$ to be the subgroup of $PGL(2,\mathcal{K})$ generated by $I^0$ and $\sigma = \begin{pmatrix}
        0 & 1 
        \\
        t & 0
    \end{pmatrix}$ (note that $\sigma^2=e$ in $PGL_2(\mathcal{K})$).

Note that

    \begin{equation}
    \label{conjunction_by_sigma}
        \sigma \begin{pmatrix}
            1+ta & b \\
            tc  & 1+td
        \end{pmatrix} \sigma^{-1}
    =
    \begin{pmatrix}
            1+td & c \\
            tb  & 1+ta
        \end{pmatrix}
    \end{equation}
    so $\sigma$ normalizes $I^0$.

Let $\psi:\mathbb{F}_q^+ \to \mathbb{C}^\times$ be a nontrivial character of the additive group of $\mathbb{F}_q$. Define $\chi:I^0 \to \mathbb{C}$ to be a character given by
    \begin{equation}
        \chi \left( \begin{pmatrix}
            1+ta & b \\
            tc  & 1+td
        \end{pmatrix} \right) = \psi(b_0+c_0)
    \end{equation}
    Note that due to \eqref{conjunction_by_sigma} $\chi:I^0 \to \mathbb{C}$ is normalized by $\sigma$ so it also defines a character (with a slight abuse of notation) $\chi:A=I^0 \rtimes\mathbb{Z}/2\mathbb{Z} \to \mathbb{C}$.

We have a decomposition 
    \begin{equation}
    \label{decomposition}
        PGL(2,\mathcal{K})=B(\mathcal{K})\cdot A
    \end{equation}

Let $M = \begin{pmatrix}
    m_{11}&& m_{12}
    \\
    m_{21} && m_{22}
\end{pmatrix}$ with $m_{ij}\in \mathcal{K}$ be a matrix representing some given element of $PGL(2,\mathcal{K})$.

Case 1: Suppose either $m_{21}=0$ or $m_{22}=0$. Then $M$ lies in $B(\mathcal{K})$ or $B(\mathcal{K})\cdot \sigma$ respectively. From now on we assume $m_{21}\neq 0$ and $m_{22}\neq 0$.

Case 2: Suppose that $val(m_{21})>val(m_{22})$  - note that this is a well defined condition for an element of $PGL(2,\mathcal{K})$. In this case we can assume that $m_{22} \in 1+t\mathcal{O}$ and $m_{21}\in t\mathcal{O}$ (recall that we can multiply all of the $m_{ij}$ by the same element of $\mathcal{K}$ without changing the class in $PGL_2(\mathcal{K})$). Consider the decomposition
\begin{equation}
    \begin{pmatrix}
        m_{11}&& m_{12}
    \\
    m_{21} && m_{22}
    \end{pmatrix}
    =
    \begin{pmatrix}
        m_{11}-m_{12} && \frac{m_{12}}{m_{21}}
        \\
        0 && 1
    \end{pmatrix}
    \cdot
    \begin{pmatrix}
        1 && 0
        \\
        m_{21} && m_{22}
    \end{pmatrix}.
\end{equation}
One sees that since $m_{22} \in 1+t\mathcal{O}$ and $m_{21}\in t\mathcal{O}$ the right hand side lies in $B(\mathcal{K})\cdot I^0 \subset B(\mathcal{K})\cdot A$.

Case 3: Suppose that $val(m_{21}) \leq val(m_{22})$. In this case we can assume that $m_{21} = t$ and $m_{21}\in t\mathcal{O}$. With that in mind consider the decomposition
\begin{multline}
    \begin{pmatrix}
        m_{11}&& m_{12}
    \\
    t && m_{22}
    \end{pmatrix}
    =
    \begin{pmatrix}
        m_{12}-\frac{m_{11}m_{22}}{t} && \frac{m_{11}}{t}
        \\
        0 && 1
    \end{pmatrix}
    \cdot
    \begin{pmatrix}
        0 && 1
        \\
        t && 0
    \end{pmatrix}
    \cdot
    \begin{pmatrix}
        1 && m_{22}
        \\
        0 && 1
    \end{pmatrix}
    =
    \\
    =
    \begin{pmatrix}
        m_{12}-\frac{m_{11}m_{22}}{t} && \frac{m_{11}}{t}
        \\
        0 && 1
    \end{pmatrix}
    \cdot
    \begin{pmatrix}
        0 && 1
        \\
        t && m_{22}
    \end{pmatrix}.
\end{multline}

One sees that the right hand side lies in $B(\mathcal{K})\cdot (\sigma \cdot I^0) \subset B(\mathcal{K})\cdot A$.

By definition every element of $V$ is locally constant on $PGL_2(\mathcal{K})$ so $V$ is admissible. Therefore to prove cuspidality of $V$ we only to show that it is quasi-cuspidal, i.e. that any $U(\mathcal{K})$-invariant functional on $V$ is zero. 
We will show that no orbit of $U(\mathcal{K})\times A$ on $PGL_2(\mathcal{K})$ (where $U(\mathcal{K})$ acts on $PGL_2(\mathcal{K})$ by multiplication on the left and $A$ by multiplication on the right) can support functionals that are invariant with respect to $U(\mathcal{K})$ and change under the character $\chi$ with respect to the action of $A$ (that is, a restriction of any such functional to such orbit must be zero). Due to the Decomposition \eqref{decomposition} it is enough to consider orbits of elements of $B(\mathcal{K})$, so take some $g = \begin{pmatrix}
    a && b
    \\
    0 &&1
    \end{pmatrix}\in G$ . We want to describe the stabilizer of $g$ under the action of $U(\mathcal{K}) \times A$, i.e. the set of solutions of the matrix equation $\overline{u}gi=g$ with $\overline{u} \in U(\mathcal{K})$ and $i \in A$. This is equivalent to $g^{-1}\overline{u}g = i$, so we compute
    \begin{multline}
    i=g^{-1}\overline{u}g = \begin{pmatrix}
            \frac{1}{a} && -\frac{b}{a}
            \\
            0 && 1
        \end{pmatrix}
        \begin{pmatrix}
            1 && u
            \\
            0 && 1
        \end{pmatrix} 
        \begin{pmatrix}
            a && b
            \\
            0 && 1
        \end{pmatrix}
        =
        \begin{pmatrix}
            1 && \frac{u}{a}
            \\
            0 && 1
        \end{pmatrix}
    \end{multline}
    Note that if we take $u=a$ then the right hand side lies in $I^0$ and $\chi(i) \neq 0$, so this orbit cannot support functionals which satisfy the necessary  conditions.

    Now let us show that $V$ is irreducible. Recall that the category of cuspidal representations of $G$ is semi-simple, therefore to establish irreducibility of $V$ it is enough to show that $\text{dim} Hom(V,V) \le 1$. Denote (following \cite{gk}) by $C^{-\infty}(A,\chi \backslash G / A, \chi)$ the space of distributions which are equivariant against the character $\chi$  with respect to left and right action of $A$. Since by definition $V =\text{ind}_{A}^{G}(\mathbb{C},\chi)$ we have an embedding 
    \begin{equation}
        Hom(V,V) \hookrightarrow C^{-\infty}(A,\chi \backslash G / A, \chi)
    \end{equation} given by $F \mapsto ev_e \circ F$ where $ev_e$ is the evaluation at the identity element of $G$. Therefore it is enough to show that $\text{dim} \left( C^{-\infty}(A,\chi \backslash G / A, \chi) \right) \le 1$. We do this by showing that there at most one $A \times A$ orbit on $G$ which can support a distribution equivariant against a character $(\chi,\chi)$. 

    Since $\chi(\sigma)=0$ it is enough to show that there is only one $I^0 \times I^0$ orbit on $G$ which can support a distribution equivariant against a character $(\chi,\chi)$. Such orbits are parametrized by a product of the affine Weyl group and the Cartan torus inside $G=PGL_2(\mathcal{K})$, that is by matrices of the form
    \begin{equation}
        \begin{pmatrix}
            at^n & 0
            \\
            0 & 1
        \end{pmatrix} \text{   and   }
        \begin{pmatrix}
            0 && at^n
            \\
            1 && 0
        \end{pmatrix}.
    \end{equation} 

    We want to show that only one such matrix has a stabilier in $I^0 \times I^0$ on which the character $(\chi, \chi)$ is trivial. To parametrize the corresponding stabilizer note that describing solutions of $h_1gh_2=g$ with $h_1,h_2 \in I^0$ and $g$ of the form given above is equivalent to describing solutions of $gh_1g^{-1} \in I^0$. 

    Now if $g$ is of the form $\begin{pmatrix}
            at^n & 0
            \\
            0 & 1
        \end{pmatrix}$ we compute

    \begin{equation}
        \begin{pmatrix}
            at^n && 0
            \\
            0 && 1
        \end{pmatrix}
        \begin{pmatrix}
            1+t\alpha && \beta
            \\
            t\gamma && 1+t\varepsilon
        \end{pmatrix}
        \begin{pmatrix}
            a^{-1}t^{-n} && 0
            \\
            0 && 1
        \end{pmatrix}
        = \begin{pmatrix}
            1 + t\alpha && at^n\beta
            \\
            a^{-1}t^{-n+1}\gamma && 1+t\varepsilon
        \end{pmatrix}
    \end{equation}
    which lies in $I^0$ if and only if $val(\gamma) \ge n$. We see that if applying an element of a stabilizer of $g$ must multiply a $(\psi,\psi)$-equivariant distribution by 
    $\psi(\beta^{(0)} + \gamma^{(0)} + a\beta^{(0)} +a^{-1}\gamma^{(0)})$ if $n=0$ and $\psi(\beta^{(0)}+a^{-1}\gamma^{(n)})$ if $n>0$.
    So the only $g$ for which $(\chi,\chi)$ is identically trivial on the corresponding stabilizer is $g=\begin{pmatrix}
        1 && 0
        \\
        0 && 1
    \end{pmatrix}$. 

    On the other hand if $g$ has the form $\begin{pmatrix}
        0 && at^n
        \\
        1 && 0
    \end{pmatrix}$
    then

    \begin{equation}
        \begin{pmatrix}
            0 && at^n
            \\
            1 && 0
        \end{pmatrix}
        \begin{pmatrix}
            1+t\alpha && \beta
            \\
            t\gamma && 1+t\varepsilon
        \end{pmatrix}
        \begin{pmatrix}
            0 && at^n
            \\
            1 && 0
        \end{pmatrix}
        = \begin{pmatrix}
            a + at^{n+1}\varepsilon && a^2t^{n+1}\alpha
            \\
            t^{-n}\beta && a+at\alpha
        \end{pmatrix}
    \end{equation}
    which lies in $I^0$ if and only if $val(\beta) \ge n+1$. We see that applying an element of a stabilizer of $g$ must multiply a $(\chi,\chi)$-equivariant distribution by $\psi(\beta^{(0)} + \gamma^{(0)}+ \beta^{(1)})$
    so the character $(\chi,\chi)$ is not trivial on the stabilizer of $g$.

    Therefore, the only $A\times A$-orbit that can support a $(\chi,\chi)$-equivariant distribution is the orbit if the identity element, so 
    \begin{equation}
        \text{dim} Hom(V,V) \le dim C^{-\infty}(A,\chi \backslash G / A, \chi) \le 1
    \end{equation} as required.

\label{first_condition_on_relevance}
    Orbit of a matrix $\begin{pmatrix}
        a & b
        \\
        0 & 1
    \end{pmatrix}$ can support functions that are twisted-equivariant with respect to $(1+t^k\mathcal{O})\times A$ with character $(0,\chi)$ if and only if $val(\frac{b}{a}) \in \{-k+1 ,...,-1\}$

Let 
    \begin{equation}
        g = \begin{pmatrix}
        at^n && b
        \\ 0 && 1
    \end{pmatrix} \text{   and   }h = \begin{pmatrix}
        1 +t^kx && 0 
        \\
        0 && 1
    \end{pmatrix}.
    \end{equation}
    Then a direct calculation shows that
    \begin{equation}
        g^{-1}hg = \begin{pmatrix}
            1+t^kx && t^kx\frac{b}{a}
            \\
            0 && 1
        \end{pmatrix}
    \end{equation}
    therefore to have $\chi(g^{-1}hg)=0$ for all $h \in \mathcal{O}$ we must have $val(\frac{b}{a}) = \{ -k+1,...,-1\}$.

\label{lemma_representatives}
    Denote by $R_{n,k}$ the set of matrices of the form  
    \begin{equation}
    \label{R_rep}
    R_{a,b}=
        \begin{pmatrix}
        a_nt^n & b_{n-k+1}t^{n-k+1}+ ... + b_{n-1}t^{n-1}
        \\
        0 & 1
    \end{pmatrix}
    \end{equation}
    where $a=a_n\in\mathbb{F}_q^\times$ and $b=b_{n-k+1}t^{n-k+1}+ ... + b_{n-1}t^{n-1}$ with $b_i \in \mathbb{F}_q$. Then $R_{n,k}$ contains a unique representative of every $(1+t^k\mathcal{O})\times A$-orbit which supports functions equivariant with character $(0,\chi)$.

We know from Claim \ref{first_condition_on_relevance} that in every relevant right $A$-coset there is a Borel matrix $\begin{pmatrix}
        a & b
        \\
        0 & 1
    \end{pmatrix}$ with $val(b)<val(a)$. Now let us provide a general form of a right $I^0$-coset of a Borel matrix:

\begin{equation}
     \begin{pmatrix}
        a & b
        \\
        0 & 1
    \end{pmatrix}
     \begin{pmatrix}
        1+tm_{11} & m_{12}
        \\
        tm_{21} & 1+tm_{22}
    \end{pmatrix}
    = 
     \begin{pmatrix}
        a+tam_{11}+tbm_{21} & am_{12}+b+tbm_{22}
        \\
        tm_{21} & 1+tm_{22}
    \end{pmatrix}.
\end{equation}

Therefore, if we take $m_{21}=0$ and $m_{22}=0$ as well as
\begin{equation}
    m_{11}=\frac{-a+a_{val(a)}t^{val(a)}}{ta}
\end{equation} 
(which lies in $\mathcal{O}$ because $val(a-a_{val(a)}t^{val(a)}) \ge val(a)+1 = val(ta)$) and
\begin{equation}
    m_{12}= -\frac{b_{val(a)}t^{val(a)}+...}{a} \in \mathcal{O}
\end{equation}
then we can turn $\begin{pmatrix}
        a & b
        \\
        0 & 1
    \end{pmatrix}$ with $val(b)<val(a)$ into a matrix of the form
    \begin{equation}
    \label{R_rep}
        \begin{pmatrix}
        a_nt^n & b_{n-k+1}t^{n-k+1}+ ... + b_{n-1}t^{n-1}
        \\
        0 & 1
    \end{pmatrix}
    \end{equation}
    and since such $m_{i,j}$ above are uniquely defined the class $R$ of matrices of the form \eqref{R_rep} contains a unique representative from each relevant orbit.

One can see from the proof that for a Borel matrix $\begin{pmatrix}
        a & b 
        \\
        0 & 1
    \end{pmatrix}$ its representative (modulo $A$) in $R$ is given by 
    \begin{equation}
        \begin{pmatrix}
        a_n t^n & b_{n-k+1}t^{n-k+1}+...+b_{n-1}t^{n-1} 
        \\
        0 & 1
    \end{pmatrix}
    \end{equation}
    where $n=val(a)$ and $k=val(a)-val(b)+1$ (so that $val(b)=n-k+1$).

\label{def_phi_B}
    We denote by $\phi_B$ and $\phi_R$ the restrictions of $\phi$ to $B(\mathcal{K})$ and $R$: $\phi_B=\phi \circ (res_B)^{-1}$ and $\phi_R=\phi \circ (res_R)^{-1}$. Note that $\phi_B$ is given by the same formula as $\phi$, except that $f$ is now formally an element of $B(\mathcal{K})/(U(\mathcal{O},\chi))$:
    \begin{equation}
        \phi_B(f)(x) = l(x.f) = \int\limits_{u \in U(\mathcal{O})}f(xu)\chi^{-1}(u)du
    \end{equation}.

\label{kernel_computation}
    The value of $\phi_R(\delta_M^{(R)})$ at a point $x\in \mathcal{K}$ is given by:
    \begin{equation}
         \phi_R(\delta_M^{(R)})(x)= 
\begin{cases}
    -q \left( \frac{b}{x}\right)_0,& \text{if } \frac{x}{a} \in 1+t\mathcal{O}\\
    0,              & \text{otherwise}
\end{cases}
    \end{equation}
    where $q=vol(\mathcal{O})$.

Under the isomorphism
\begin{equation}
    PGL_2(\mathcal{K})/(A,\chi) \simeq B(\mathcal{K})/(U(\mathcal{O},\chi)) \simeq C^\infty(R)
\end{equation}
the function $\delta_M^{(R)}$ corresponds to a function $\delta_M^{(B)} \in B(\mathcal{K})/(U(\mathcal{O},\chi))$ given by 
\begin{equation}
    \delta_M^{(B)}(N) = \begin{cases}
    \chi(u),& \text{if } N = M\cdot u \text{ with } u\in U(\mathcal{O})\\
    0,              & \text{otherwise}
\end{cases}.
\end{equation}
By definition

\begin{equation}
\label{p_expression}
    \phi_R(\delta_M^{(R)})(x) =\phi_B(\delta_M^{(B)})(x) = \int\limits_{u \in U(\mathcal{O})} \delta_M^{(B)}(xu)\chi^{-1}(u)du = \int\limits_{S} \chi(s(u))\chi^{-1}(u)du
\end{equation}

where
\begin{equation}
    S = \big\{ u \in U(\mathcal{O}) \Big| xu=M\cdot s(u) \text{ with } s(u) \in A \big\}.
\end{equation}

Condition $xu=M\cdot s(u) \text{ with } s(u) \in A$ is equivalent to
\begin{equation}
\label{m_id_1}
    \begin{pmatrix}
    a & b
    \\
    0 & 1
\end{pmatrix}
\begin{pmatrix}
    \alpha & \beta
    \\
    0 & 1
\end{pmatrix}
=
\begin{pmatrix}
    x & xu
    \\
    0 & 1
\end{pmatrix}.
\end{equation}

Now in \eqref{p_expression} we are given  $x \in \mathcal{K}^\times$, $a = a_nt^n \in \mathbb{F}_q^\times t^n$ and $b=b_{n-k+1}t^{n-k+1}+...+b_{n-1}t^{n-1} \in \mathcal{K}^\times$ and we need to describe all $u \in\mathcal{O}$ for which there exist $\alpha \in 1+t\mathcal{O}$ and $\beta \in \mathcal{O}$ such that \eqref{m_id_1} is satisfied. The conditions on all these variables coming from \eqref{m_id_1} are $a \cdot \alpha=x$ and $a\beta +b=xu$. From this we see that:
\begin{itemize}
    \item $ \phi_R(\delta_M^{(R)})(x)=0$ unless $\frac{x}{a} \in 1+t\mathcal{O}$.
    \item If $\frac{x}{a} \in 1+t\mathcal{O}$, then we are forced to set $\alpha = \frac{x}{a}$. Then the remaining condition is
    $a\beta +b=xu$ which is the same as $u = \frac{a}{x}\beta+ \frac{b}{x}$. That is, $u$ is parametrized by $\beta \in \mathcal{O}$ and in such a way that
    \begin{equation}
        \chi\left( \begin{pmatrix}
    1 & u(\beta)
    \\
    0 & 1
\end{pmatrix} \right) = \left( u(\beta) \right)_0=\beta_0+\left( \frac{b}{x}\right)_0.
    \end{equation}
\end{itemize}


Therefore, the integral in \eqref{p_expression} can be calculated as an integral over $\beta \in \mathcal{O}$:

\begin{multline}
    \phi_R(\delta_M^{(R)})(x) = \int\limits_{u \in U(\mathcal{K})} \delta_M^{(R)}(xu)\chi^{-1}(u)du = \int\limits_{\beta\in \mathcal{O}} \chi(M^{-1}\cdot x \cdot u(\beta))\chi^{-1}(u(\beta))d\beta =
    \\
    =
    \int\limits_{\beta \in \mathcal{O}} \chi \left( 
    \begin{pmatrix}
        \frac{1}{a} & -\frac{b}{a} 
        \\
        0 & 1
    \end{pmatrix}
    \begin{pmatrix}
        x & 0 
        \\
        0 & 1
    \end{pmatrix}
    \begin{pmatrix}
        1 & u(\beta)
        \\
        0 & 1
    \end{pmatrix}
    \right)
    \chi^{-1} \left(
    \begin{pmatrix}
        1 & u(\beta)
        \\
        0 & 1
    \end{pmatrix}
    \right)
    d\beta 
\end{multline}
and since
\begin{multline}
    \begin{pmatrix}
        \frac{1}{a} & -\frac{b}{a} 
        \\
        0 & 1
    \end{pmatrix}
    \begin{pmatrix}
        x & 0 
        \\
        0 & 1
    \end{pmatrix}
    \begin{pmatrix}
        1 & u(\beta)
        \\
        0 & 1
    \end{pmatrix} 
    =
    \begin{pmatrix}
        \frac{1}{a} & -\frac{b}{a} 
        \\
        0 & 1
    \end{pmatrix}
    \begin{pmatrix}
        x & xu(\beta)
        \\
        0 & 1
    \end{pmatrix} =
    \\
    = 
    \begin{pmatrix}
        \frac{1}{a} & -\frac{b}{a} 
        \\
        0 & 1
    \end{pmatrix}
    \begin{pmatrix}
        x & a\beta+b
        \\
        0 & 1
    \end{pmatrix}
    =
    \begin{pmatrix}
        \frac{x}{a} & \beta + \frac{b}{a} - \frac{b}{a}
        \\
        0 & 1
    \end{pmatrix}
    =\begin{pmatrix}
        \frac{x}{a} & \beta
        \\
        0 & 1
    \end{pmatrix},
\end{multline}
we have (if $\frac{x}{a} \in 1+t\mathcal{O}$) the following expression for $\phi_R(\delta_M^{(R)})(x)$:
\begin{equation}
     \phi_R(\delta_M^{(R)})(x) = \int\limits_{\beta \in \mathcal{O}} ( \beta_0 - u(\beta))_0 ) d\beta=  q \left( \beta_0-\beta_0- \left( \frac{b}{x}\right)_0 \right)= -q \left( \frac{b}{x}\right)_0
\end{equation}
where $q=vol(\mathcal{O})$.

\label{kernel}
    The isomorphism $\phi:V=PGL_2(\mathcal{K})/(A\chi)\to C^\infty(\mathcal{K}^\times)$ of Theorem \ref{gk_theorem} can be realized as 
    \begin{equation}
        \phi=\phi_R \circ res_R
    \end{equation} where 
    \begin{equation}
        res_R:PGL_2(\mathcal{K})/(A\chi)\to C^\infty(R)
    \end{equation} is the restriction and 
        \begin{equation}
            \phi_R = pr_{2*}(K\cdot pr_1^*(\bullet))
        \end{equation}
with $pr_1: R \times \mathcal{K}^\times \to R$ and $pr_2: R \times \mathcal{K}^\times \to \mathcal{K}^\times$ the natural projections and the kernel function $K:R \times \mathcal{K}^\times \to \mathbb{C}$ is given by
\begin{equation}
\label{formula_kernel}
    K: \begin{pmatrix}
        a && b
        \\
        0 && 1
    \end{pmatrix}\times x \mapsto \begin{cases}
    -q \left( \frac{b}{x}\right)_0,& \text{if } \frac{x}{a} \in 1+t\mathcal{O}\\
    0,              & \text{otherwise}
\end{cases}.
\end{equation}

We say that a category $\mathcal{A}$ equipped with a strong action of a reductive group $G$ is a cuspidal irreducible categorical representation of $G$ if:
    \begin{enumerate}
        \item it is cuspidal, meaning that the invariants with respect to the action of $U(\mathcal{K})$ are trivial and
        \item the Whittaker invariants functor provides an equivalence between $\mathcal{A}$ and the category $Vect$ of vector spaces.
    \end{enumerate}

Given a $(A,\chi)$-equivariant sheaf $\mathcal{F}$ on $PGL_2(\mathcal{K})$, we first restrict it to the Borel subgroup and then apply Whittaker-averaging over $U(\mathcal{O})$ with respect to the character $\chi^{-1}$:
\begin{equation}
    P (\mathcal{F}) = Avg^{(U)}_{\chi^-1} \circ res_B (\mathcal{F}).
\end{equation}
One easily sees that this expression mimics the realization of $\phi$ as $\phi=\phi_B\circ res_B$ from Definition \ref{def_phi_B} of the previous section.

\begin{remark}
\label{remark_compact_objects}
A key technical point is that to establish that this functor is an equivalence it is enough to check this on the level of subcategories formed by $D$-modules equivariant with respect to the action of $k$-th congruence subgroups on both sides for each $k$. The reason is that the categories in question are compactly generated and $D$-modules equivariant with respect to the congruence subgroups are precisely the compact objets on both sides. For this reason every statement below is formulated in terms of some fixed (but arbitrary) $k$.
\end{remark}

Since this morphism is injective it is enough to check the valuative criterion of closedness. The schemes in question are of finite type over an algebraically closed field $\mathbb{C}$, so it is enough to check the criterion for $O = \mathbb{C}[[\lambda]]$ and $\mathcal{K}=Frac(O)=\mathbb{C}((\lambda))$.

    So, let $z \in (1+t^k\mathcal{O})$, $r \in R(\mathcal{K})$ and $w \in I^0(\mathcal{K})$ be such that for their product we have $z \cdot r\cdot w = m(z,r,w) \in PGL_2(O)$. We will show that then necessarily $r \in R(O)$ and $w \in I^0(O)$.  Indeed, if
    \begin{equation}
        r = \begin{pmatrix}
            a && b
            \\
            0 && 1
        \end{pmatrix}
    \end{equation}
    where $a \in \mathbb{C}((\lambda))$, $b = b^{(n-k+1)}t^{n-k+1} + ... + b^{(n-1)}t^{n-1} \in \mathbb{C}((\lambda))((t))$ and
    \begin{equation}
        w = \begin{pmatrix}
            1+t\alpha && \beta
            \\
            t\gamma && 1+t \varepsilon
        \end{pmatrix}
    \end{equation}
    where $\alpha, \beta,\gamma,\varepsilon \in \mathbb{C}((\lambda))[[t]]$ and $\alpha^{(i)}, \beta^{(i)},\gamma^{(i)},\varepsilon^{(i)} \in \mathbb{C}((\lambda))$ are the  coefficients of $t^i$ in the corresponding element of $\mathbb{C}((\lambda))[[t]]$.
    Then 
    \begin{equation}
        z\cdot r\cdot w =  \begin{pmatrix}
            a(1+t\alpha)z+b\cdot (t\gamma)z && a\cdot \beta\cdot z + b\cdot (1+t \varepsilon)\cdot z
            \\
            t\gamma && 1+t \varepsilon
        \end{pmatrix} = : \begin{pmatrix}
            m_{11} && m_{12}
            \\
            m_{21} && m_{22}
        \end{pmatrix}.
    \end{equation}

    By assumption, this product lies in $PGL_2(\mathbb{C}[[\lambda]][[t]])$.
    First of all, this means that $t\gamma$ and $1+t \varepsilon$ are both elements of $\mathbb{C}[[\lambda]][[t]])$.

    Then consider the upper-right coefficient $m_{12}$ of the product. Recall that $val(a)=n$, $val(\beta) \ge 0$ and $val ( 1+t\varepsilon) =0$, while $b = b^{(n-k+1)}t^{n-k+1} + ... + b^{(n-1)}t^{n-1}$ and $z \in (1+t^k\mathcal{O})$. One easily sees that it implies that $b \in \mathbb{C}[[\lambda]][[t]]$. Indeed, suppose there is $j \in \mathbb{Z}$ which is the minimal integer such that $b^{(i)} \notin \mathbb{C}[[\lambda]]$. Then the coefficient of $t^j$ in $m_{12}$ is equal to 
    \begin{equation}
        m_{12}^{(j)} = b^{(j)} + b^{(j-1)}\varepsilon{(0)} + ... + b^{(n-k+1)}\varepsilon^{(j-n+k-1)}
    \end{equation}
    but we already know that $\varepsilon \in \mathbb{C}[[\lambda]][[t]])$, by assumption $m_{12} \in \mathbb{C}[[\lambda]][[t]])$ and all of the $b^{(i)} \in \mathbb{C}[[\lambda]][[t]])$ for $i<j$ due to our choice of $j$. This is a contradiction, therefore $b \in \mathbb{C}[[\lambda]][[t]]$.

    Finally, consider $m_{11} = a(1+t\alpha)z+b\cdot (t\gamma)\cdot z$ which by assumption lies in $\mathbb{C}[[\lambda]][[t]]$. We also already know that $b$ and $\gamma$ are elements of $\mathbb{C}[[\lambda]][[t]]$. Therefore $a(1+t\alpha)z = m_{11}- b\cdot(t\gamma)z \in \mathbb{C}[[\lambda]][[t]]$ so $a \in \mathbb{C}[[\lambda]]$.

    Since $a \in \mathbb{C}[[\lambda]]$ and $b \in \mathbb{C}[[\lambda]][[t]]$, we see that $r$ actually lies in $PGL_2(\mathbb{C}[[\lambda]])$. By assumption, so does $r\cdot w$ therefore so does $w$.

Denote by $\mathcal{L}_\chi$ the exponential $D$-module on $\mathbb{A}^1$ defined by the character $\chi$. 

    By definition,
    \begin{equation}
    P = Avg^{(U)}_{\chi^-1} \circ res_B  = pr_{1 \; *}\left( (u_0)^{*}\mathcal{L}_{-\chi} \otimes m_2^{*} (\bullet) \right)
\end{equation}

Due to the Corollary \ref{decomposition_corollary} and Remark \ref{remark_compact_objects} it is actually enough to show that $P$ provides an equivalence between the subcategories of $(1+t^k\mathcal{O})$-equivariant objects supported on the subvarieties $R_{n}\cdot A \subset PGL_2(\mathcal{K})$ and $\mathcal{K}_n := t^n\mathcal{O}^\times \subset \mathcal{K}$ respectively. There is a natural equvalence between the category of $(1+t^k\mathcal{O})$-equivariant $D$-modules on $\mathcal{K}_n$ and the category $D(\mathcal{K}_{n,k})$ on $\mathcal{K}_{n,k}$. Also, every $(1+t^k\mathcal{O})$-equivariant object the category $D(PGL_2(\mathcal{K}))_{/(A,\chi)}$ supported on the subvariety $R_{n}\cdot A \subset PGL_2(\mathcal{K})$ comes as an image of a $D$-module on $R_{n,k}$ under the functor
\begin{equation}
    D(R_{n,k}) \ni \mathcal{F} \mapsto \Tilde{\mathcal{F}} := m_{1*}(\mathcal{F} \boxtimes ( \beta_0)^{*}\mathcal{L}_\psi) \in D(PGL_2(\mathcal{K}))_{/(A,\chi)}
\end{equation}
so it is enough to show that the functor $D(R_{n,k}) \to D(\mathcal{K}_{n,k})$ which sends $\mathcal{F} \in D(R_{n,k})$ to 
\begin{equation}
    P(\Tilde{\mathcal{F}}) = pr_{1 \; *}\left( (u_0)^{*}\mathcal{L}_{-\psi} \otimes m_2^{*}m_{1*}(\mathcal{F} \boxtimes ( \beta_0)^{*}\mathcal{L}_\psi)  \right)
\end{equation}
is an equivalence.


Tracing these functors on the diagram \ref{the_diagram} one sees that due to "closed base change" we have 
    \begin{multline}
        P(\Tilde{\mathcal{F}}) = pr_{1 \; *}\left( (u_0)^{*}\mathcal{L}_{-\psi} \otimes m_2^{*}m_{1*}(\mathcal{F} \boxtimes ( \beta_0)^{*}\mathcal{L}_\psi)  \right) \simeq
        \\
        \simeq
        pr_{1 \; *}\left( (u_0)^{*}\mathcal{L}_{-\psi} \otimes \phi_{2*}\phi_{1}^*(\mathcal{F} \boxtimes ( \beta_0)^{*}\mathcal{L}_\psi)  \right) 
        \end{multline}
        which in turn is isomorphic to
        \begin{multline}
        \simeq (pr_1 \circ \phi_2)_* 
        \left( (\beta+\frac{b}{x})_0^*\mathcal{L}_{-\psi} \otimes \phi_{1}^*(\mathcal{F} \boxtimes ( \beta_0)^{*}\mathcal{L}_\psi)  \right) \simeq
        \\
        \simeq 
        (pr_1 \circ \phi_2)_*
        \left(
        (\beta+\frac{b}{x})_0^*\mathcal{L}_{-\psi} \otimes ( \beta_0)^{*}\mathcal{L}_\psi \otimes (pr_R \circ \phi_{1})^*\mathcal{F}
        \right)
        \simeq
        \\
         \simeq (pr_1 \circ \phi_2)_*
        \left(
        K^*\mathcal{L}_{-\psi} \otimes (pr_R \circ \phi_{1})^*\mathcal{F}
        \right)
    \end{multline}
Where $K$ is given by the formula (\ref{formula_kernel}).

Now note that:
\begin{enumerate}
    \item The map 
    \begin{equation}
        p_1= pr_R \circ \phi_{1}: \mathbb{G}_m\times\mathbb{A}^{k-1}\times\mathbb{A}^{k-1}\times\mathcal{O} \to R_{n,k} \simeq \mathbb{G}_m\times \mathbb{A}^1
    \end{equation}
    sends the tuple $(a,b,[\frac{x}{a}]_{1+t^k\mathcal{O}},\beta)$ to $\begin{pmatrix}
        a && b
        \\
        0 && 1
    \end{pmatrix}$
    \item The map 
    \begin{equation}
        p_2 = pr_1 \circ \phi_2: \mathbb{G}_m\times\mathbb{A}^{k-1}\times\mathbb{A}^{k-1}\times\mathcal{O} \to \mathcal{K}_{n,k} \simeq \mathbb{G}_m\times \mathbb{A}^1
    \end{equation}
    sends the tuple $(a,b,[\frac{x}{a}]_{1+t^k\mathcal{O}},\beta)$ to $[x]_{1+t^k\mathcal{O}}= a\cdot [\frac{x}{a}]_{1+t^k\mathcal{O}}$
    \item $K(a,b,[x])_{1+t^k\mathcal{O}}$ defines a morphism $\mathbb{G}_m\times\mathbb{A}^{k-1}\times\mathbb{A}^{k-1} \to \mathbb{A}^1$ which is nonzero if and only if $\frac{x}{a} \in $, in which case is $K(a,b,[x])= (\frac{b}{x})_0$. 
    \item From the expressions above one sees that the maps $p_1$ and $p_2$ commute with projections to the $\mathbb{G}_m$, so the diagram

\[\begin{tikzcd}
	{\mathbb{G}_m \times \mathbb{A}^{k-1}\times\mathbb{A}^{k-1}\times\mathcal{O}} && {\mathbb{G}_m \times \mathbb{A}^{k-1}_b} \\
	\\
	{\mathbb{G}_m \times \mathbb{A}^{k-1}_{[\frac{x}{a}]}}
	\arrow["{p_1}"', from=1-1, to=1-3]
	\arrow["{p_2}", from=1-1, to=3-1]
\end{tikzcd}\]

can be viewed as a diagram of (trivial) vector bundles over $\mathbb{G}_m$. The factor of $\mathcal{O}$ can be ignored because from the expression for $p_2$ above we see that the only effect it has is multiplication by the cohomology of the pushforward of the structure sheaf of $\mathcal{O}$, which is a one-dimensional vector space since $\mathcal{O}$ is contractible. 

\item The map $K: \mathbb{G}_m\times\mathbb{A}^{k-1}\times\mathbb{A}^{k-1} \to \mathbb{A}^1$ (note that this is well-defined since $K$ ignores the factor of $\mathcal{O}$) then induces a fiberwise nondegenerate pairing which identifies fibers of the upper-right bundle with duals to the fibers of the bottom bundle. Indeed, a change of coordinate $z=\frac{1}{x}$ takes the form $K(b,z)=(b,z)_0$, which with our assumptions on $b$ and $z$ (recall that $x\in at^n\mathcal{O}^\times/(1+t^k\mathcal{O})$ and $b= b_{n-k+1}t^{n-k+1}+ ... + b_{n-1}t^{n-1}$) is easily seen to be a nondegenerate pairing. 

\item Therefore we see that our functor is just a Fourier-Deligne transform between vector bundles over $\mathbb{G}_m$ with respect to the kernel given by $K$, hence it is an equivalence.
\end{enumerate}
